// @bun
// src/index.ts
import {
  accessSync,
  appendFileSync,
  constants,
  existsSync,
  mkdirSync,
  readdirSync,
  statSync
} from "fs";
import { delimiter, dirname, join } from "path";
import { fileURLToPath } from "url";
var LOG_FILE = join(process.cwd(), ".opencode", "event-log.txt");
var BUNDLED_SKILLS_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "skills");
var HOST_ENV_VAR = "JFROG_PLATFORM_URL";
var JF_CLI_INSTALL_HINT = "JFrog: the `jf` CLI was not found on your PATH. Install it " + "(https://jfrog.com/getting-started-with-jfrog-cli/) to run JFrog commands and `jf setup <pm>`.";
var isNonEmptyDir = (dir) => {
  try {
    return existsSync(dir) && statSync(dir).isDirectory() && readdirSync(dir).length > 0;
  } catch {
    return false;
  }
};
var commandExists = (cmd) => {
  const names = process.platform === "win32" ? [`${cmd}.exe`, `${cmd}.cmd`, `${cmd}.bat`] : [cmd];
  return (process.env.PATH ?? "").split(delimiter).some((dir) => !dir ? false : names.some((name) => {
    try {
      accessSync(join(dir, name), constants.X_OK);
      return true;
    } catch {
      return false;
    }
  }));
};
var toBaseUrl = (raw) => {
  const trimmed = raw.replace(/\/+$/, "");
  return /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
};
var isJfCommand = (command) => /(?:^|[\s;&|(])jf(?:\s|$)/.test(command);
var resolveMcpCredentials = () => {
  if (process.env.JFROG_MCP_DISABLE === "true") {
    return;
  }
  const host = process.env[HOST_ENV_VAR];
  return host ? { baseUrl: toBaseUrl(host) } : undefined;
};
var mcpServerEntry = ({ baseUrl }) => ({
  type: "remote",
  url: `${baseUrl}/mcp`,
  enabled: true
});
var skillsErrorShown = false;
var registerSkills = (cfg, log, toast) => {
  cfg.skills = cfg.skills ?? {};
  cfg.skills.paths = cfg.skills.paths ?? [];
  if (!isNonEmptyDir(BUNDLED_SKILLS_DIR)) {
    if (!skillsErrorShown) {
      skillsErrorShown = true;
      const message = `JFrog: bundled skills not found at ${BUNDLED_SKILLS_DIR}. ` + "The plugin package may be broken; reinstall @jfrog/opencode-jfrog-plugin.";
      log("ERROR " + message);
      toast(message, "error");
    }
    return false;
  }
  if (!cfg.skills.paths.includes(BUNDLED_SKILLS_DIR)) {
    cfg.skills.paths.push(BUNDLED_SKILLS_DIR);
  }
  log("config.skills.paths=" + JSON.stringify(cfg.skills.paths));
  return true;
};
var registerMcp = (cfg, log) => {
  const credentials = resolveMcpCredentials();
  if (!credentials) {
    log("mcp: jfrog remote MCP not registered (need JFROG_PLATFORM_URL; or JFROG_MCP_DISABLE=true)");
    return;
  }
  cfg.mcp = cfg.mcp ?? {};
  if (cfg.mcp.jfrog) {
    return;
  }
  cfg.mcp.jfrog = mcpServerEntry(credentials);
  log(`mcp: registered jfrog remote MCP (OAuth) at ${credentials.baseUrl}/mcp`);
};
var jfrogOpencodePlugin = async ({ client }) => {
  if (!existsSync(dirname(LOG_FILE))) {
    mkdirSync(dirname(LOG_FILE), { recursive: true });
  }
  const log = (message) => {
    if (process.env.JFROG_DEBUG_LOGS === "true") {
      appendFileSync(LOG_FILE, message + `
`, "utf-8");
    }
  };
  const toast = (message, variant) => {
    client.tui.showToast({ body: { message, variant, duration: 1e4 } }).catch(() => {
      return;
    });
  };
  log("JfrogOpencodePlugin starting...");
  const hasJfCli = commandExists("jf");
  log("jf CLI on PATH: " + hasJfCli);
  let installHintShown = false;
  const adviseInstallOnce = () => {
    if (installHintShown || hasJfCli) {
      return;
    }
    installHintShown = true;
    toast(JF_CLI_INSTALL_HINT, "info");
  };
  return {
    config: async (config) => {
      const cfg = config;
      registerSkills(cfg, log, toast);
      registerMcp(cfg, log);
    },
    "tool.execute.before": async (input, output) => {
      if (installHintShown || hasJfCli || input.tool !== "bash") {
        return;
      }
      const command = String(output.args?.command ?? "");
      if (isJfCommand(command)) {
        adviseInstallOnce();
      }
    }
  };
};
var server = jfrogOpencodePlugin;
var JfrogOpencodePlugin = jfrogOpencodePlugin;
export {
  server,
  JfrogOpencodePlugin
};

# JFrog-aligned styling for standalone HTML reports

Use this reference when producing a **pretty, self-contained HTML file** (single file with embedded CSS) that presents data fetched from the JFrog Platform. It complements the operational steps in `SKILL.md`; it does not replace [JFrog Brand Guidelines](https://jfrog.com/brand-guidelines/).

## When this applies

- The user asked for HTML output (not only Markdown).
- The report should feel **professionally aligned** with JFrog’s public brand (terminology, palette, restraint) without impersonating JFrog or implying endorsement.

## Authoritative source

