{
  "data": {
    "<namespace>": {
      "<queryName>": {
        "edges": [
          {
            "node": {},
            "cursor": "abc123"
          }
        ],
        "pageInfo": {
          "hasNextPage": true,
          "endCursor": "abc123"
        },
        "totalCount": 42
      }
